<?php
namespace SenderSuite;

/** Calendar persistence only. Caller supplies authentication and a transaction. Never sends. */
final class Calendar {
    const TYPES=array('meeting','call','reminder','task','follow_up','other');
    const STATUSES=array('scheduled','confirmed','completed','cancelled','no_show');
    const DELIVERY=array('send_invite_sms','send_invite_email','send_sms_reminder','send_email_reminder');
    const INVITE="Hi {{first_name}}, you're booked in: {{meeting_title}} on {{meeting_date}} at {{meeting_time}} {{meeting_location}}Reply YES to confirm.";
    const REMINDER="Hi {{first_name}}, reminder: {{meeting_title}} {{meeting_when}} ({{meeting_date}} at {{meeting_time}}) {{meeting_location}}";
    private $db;private $records;
    public function __construct(Database $db,callable $clock=null){$this->db=$db;$this->records=new Records($db,$clock);}
    private function table($name){return Schema::identifier($this->db->schema()->table($name));}
    public static function definitions(){return array('/calendar/?'=>array('GET','POST'),'/calendar/upcoming'=>array('GET'),'/calendar/day'=>array('GET'),'/calendar/tags'=>array('GET'),'/calendar/tags/all'=>array('GET'),'/calendar/(?P<meeting_id>-?[0-9]+)'=>array('GET','PUT','DELETE'),'/calendar/(?P<meeting_id>-?[0-9]+)/preview'=>array('GET'),'/calendar/(?P<meeting_id>-?[0-9]+)/(?P<action>confirm|complete|cancel|no-show|send-invite|send-reminder)'=>array('POST'));}
    /** Strict ISO calendar inputs: avoid PHP's natural-language parser and silent date rollover. */
    public static function date($value,$field='starts_at'){
