        if(preg_match('/[+-](\d{2}):(\d{2})$/D',$value,$zone)&&((int)$zone[1]>23||(int)$zone[2]>59)){throw new ValidationFailure('Invalid timezone offset',$field);}
        try{$d=(new \DateTimeImmutable($value,new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('UTC'));$errors=\DateTimeImmutable::getLastErrors();if(($errors&&($errors['warning_count']||$errors['error_count']))||$d->format('Y')<'1000'||$d->format('Y')>'9999'){throw new \RuntimeException();}return $d->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s.u');}catch(\Throwable $e){throw new ValidationFailure('Input should be a valid ISO date or datetime',$field);}
    }
    public static function input($body,$update=false){
        if(!is_object($body)){throw new ValidationFailure('Input should be a valid object');}
        $defaults=array('title'=>null,'description'=>null,'event_type'=>'meeting','starts_at'=>null,'ends_at'=>null,'duration_minutes'=>30,'all_day'=>false,'location'=>null,'meeting_link'=>null,'contact_ids'=>array(),'conversation_id'=>null,'campaign_id'=>null,'tags'=>array(),'send_invite_sms'=>true,'send_invite_email'=>false,'invite_subject'=>null,'email_account_id'=>null,'invite_template_id'=>null,'invite_body'=>null,'send_sms_reminder'=>true,'send_email_reminder'=>false,'reminder_subject'=>null,'reminder_minutes'=>array(60,15),'reminder_template_id'=>null,'reminder_body'=>null,'outcome_notes'=>null);
        if(!$update){$defaults['contact_id']=null;}else{$defaults['status']=null;}$out=$update?array():$defaults;
        foreach($defaults as $key=>$default){
            if(!property_exists($body,$key)){if(!$update&&in_array($key,array('title','starts_at'),true)){throw new ValidationFailure('Field required',$key);}continue;}$v=$body->$key;
            $required=in_array($key,array('title','event_type','starts_at','duration_minutes','all_day','tags','contact_ids','reminder_minutes'),true)||in_array($key,self::DELIVERY,true);
            if($v===null){if(!$update&&$required){throw new ValidationFailure('Input must not be null',$key);}$out[$key]=null;continue;}
