            elseif(in_array($key,array('contact_ids','reminder_minutes'),true)){$v=DataRoutes::ids($v,$key);if(count($v)>1000){throw new ValidationFailure('List may contain at most 1000 items',$key);}}
            elseif($key==='tags'){if(!is_array($v)||count($v)>1000){throw new ValidationFailure('Input should be a bounded list',$key);}foreach($v as $tag){if(!is_string($tag)||strpos($tag,"\0")!==false||preg_match('//u',$tag)!==1){throw new ValidationFailure('Tags must be strings',$key);}}}
            elseif(substr($key,-3)==='_id'||$key==='duration_minutes'){$v=DataRoutes::integer($v,$key,$key==='duration_minutes'?5:null,$key==='duration_minutes'?1440:null);}
            else{if(!is_string($v)){throw new ValidationFailure('Input should be a valid string',$key);}$cap=array('title'=>255,'event_type'=>30,'status'=>30,'location'=>500,'meeting_link'=>1000,'invite_subject'=>500,'reminder_subject'=>500)[$key]??100000;if(Compat::length($v)>$cap||($key==='title'&&Compat::strip($v)==='')){throw new ValidationFailure('Invalid string length',$key);}}
            if($key==='meeting_link'&&is_string($v)&&Compat::strip($v)!==''){self::link($v);}
            if(is_string($v)&&(strpos($v,"\0")!==false||preg_match('//u',$v)!==1)){throw new ValidationFailure('Invalid text',$key);}$out[$key]=$v;
