    }
    private static function link($v){$v=Compat::strip($v);$parts=parse_url($v);if(preg_match('/[\x00-\x20\x7f]/',$v)||!$parts||!in_array(strtolower($parts['scheme']??''),array('http','https'),true)||empty($parts['host'])||isset($parts['user'])||isset($parts['pass'])){throw new ValidationFailure('Meeting link must be an absolute HTTP(S) URL without credentials','meeting_link');}}
    private static function cleanTags($tags){$out=array();foreach($tags??array() as $tag){$s=Compat::strip($tag);if($s!==''&&Compat::length($s)<=100&&!in_array($s,$out,true)){$out[]=$s;}}return $out;}
    private static function cleanMinutes($values){$out=array();foreach($values??array() as $n){if($n>=1&&$n<=10080&&!in_array($n,$out,true)){$out[]=$n;}}rsort($out,SORT_NUMERIC);return $out;}
    private static function listJson($value){$v=json_decode($value??'null');return is_array($v)?$v:array();}
    private function meeting($id){$r=$this->db->one('meetings',array('id'=>$id));if(!$r){throw new AuthFailure(404,'Meeting not found');}return $r;}
    private static function name($c){$person=Compat::strip(Compat::strip($c['first_name']??'').' '.Compat::strip($c['last_name']??''));if($person!==''){return $person;}foreach(array('business_name','phone_number','email') as $key){$s=Compat::strip($c[$key]??'');if($s!==''){return $s;}}return 'Unknown';}
    private function links($id){$rows=$this->db->select('meeting_attendees',array('meeting_id'=>$id),1001);if(count($rows)>1000){throw new AuthFailure(413,'Meeting attendee limit exceeded.');}return $rows;}
    public function read($id){return $this->out($this->meeting($id));}
    private function out(array $r,&$bytes=null){if($bytes===null){$bytes=0;}
        $out=$r;foreach(array('tags_json','reminder_minutes_json','reminders_sent_json','created_by') as $key){unset($out[$key]);}
        foreach(array('all_day','invite_sent','invite_email_sent','send_invite_sms','send_invite_email','send_sms_reminder','send_email_reminder') as $key){$out[$key]=(bool)$r[$key];}
        foreach(array('starts_at','ends_at','created_at','updated_at') as $key){$out[$key]=Records::iso($r[$key]);}
        $out['tags']=array_values(array_filter(array_map(function($v){return Attachments::pythonText($v);},self::listJson($r['tags_json'])),function($v){return Compat::strip($v)!=='';}));$out['reminder_minutes']=array();foreach(self::listJson($r['reminder_minutes_json']) as $n){try{$n=DataRoutes::integer($n,'reminder_minutes');if($n>0&&!in_array($n,$out['reminder_minutes'],true)){$out['reminder_minutes'][]=$n;}}catch(ValidationFailure $e){}}rsort($out['reminder_minutes'],SORT_NUMERIC);
        $sent=json_decode($r['reminders_sent_json']??'null');$out['reminders_sent']=is_object($sent)?$sent:new \stdClass();$out['attendees']=array();
        $links=$this->links($r['id']);$ids=array_column($links,'contact_id');if($r['contact_id']){$ids[]=$r['contact_id'];}$ids=array_values(array_unique($ids));$contacts=array();if($ids){foreach($this->db->rows('SELECT * FROM '.$this->table('contacts').' WHERE id IN ('.implode(',',array_fill(0,count($ids),'%d')).')',$ids) as $c){$c=$this->db->decode('contacts',$c);$contacts[$c['id']]=$c;}}
        foreach($links as $link){$c=$contacts[$link['contact_id']]??null;$out['attendees'][]=array('id'=>$link['id'],'contact_id'=>$link['contact_id'],'status'=>$link['status'],'notified'=>(bool)$link['notified'],'name'=>$c?self::name($c):'Contact #'.$link['contact_id'],'phone'=>$c?$c['phone_number']:'');}
        $primary=$contacts[$r['contact_id']]??null;$out['contact_name']=$primary?self::name($primary):null;$bytes+=strlen(json_encode($out,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));if($bytes>8388608){throw new AuthFailure(413,'Calendar response is too large. Reduce the date range or page size.');}return $out;
    }
    private function noDelivery(array $d){foreach(self::DELIVERY as $key){if(!empty($d[$key])){throw new AuthFailure(503,'Calendar delivery is not available. Disable SMS/email invitations and reminders to save a calendar-only booking.');}}}
    private function references(array $d){foreach(array('conversation_id'=>'conversations','campaign_id'=>'campaigns','invite_template_id'=>'templates','reminder_template_id'=>'templates') as $key=>$table){if(isset($d[$key])&&!$this->db->one($table,array('id'=>$d[$key]))){throw new AuthFailure(404,$key==='conversation_id'?'Conversation not found':'Referenced calendar record not found');}}}
    private function sync(array $r,array $ids){
        if(count(array_unique($ids))>1000){throw new ValidationFailure('At most 1000 attendees are supported','contact_ids');}
        $valid=array();foreach(array_unique($ids) as $id){$c=$this->db->one('contacts',array('id'=>$id));if($c){$valid[$id]=$c;}}
        $existing=array();foreach($this->links($r['id']) as $link){$existing[$link['contact_id']]=$link;if(!isset($valid[$link['contact_id']])){$this->db->delete('meeting_attendees',array('id'=>$link['id']));}}
        foreach($valid as $id=>$c){if(!isset($existing[$id])){$this->records->create('meeting_attendees',array('meeting_id'=>$r['id'],'contact_id'=>$id));}if(!in_array($c['lead_status'],array('customer','closed','not_interested'),true)&&$c['lead_status']!=='meeting'){if($this->db->update('contacts',array('lead_status'=>'meeting','updated_at'=>$this->records->now()),array('id'=>$id,'lead_status'=>$c['lead_status']))!==1){throw new AuthFailure(409,'Contact changed. Retry the booking.');}}}
        return $valid?(int)array_keys($valid)[0]:null;
    }
    private function change(array $old,array $patch,$force=false){$next=array_replace($old,$patch);if($next===$old&&!$force){return;}$stamp=$this->records->now();if($stamp<=$old['updated_at']){$stamp=(new \DateTimeImmutable($old['updated_at'],new \DateTimeZone('UTC')))->modify('+1 microsecond')->format('Y-m-d H:i:s.u');}$patch['updated_at']=$stamp;if($this->db->update('meetings',$patch,$old)!==1){throw new AuthFailure(409,'Meeting changed. Reload and retry.');}}
    public function create($body,array $user){
        $d=self::input($body);$this->noDelivery($d);$this->references($d);$start=$d['starts_at'];$end=$d['ends_at']??(new \DateTimeImmutable($start,new \DateTimeZone('UTC')))->modify('+'.$d['duration_minutes'].' minutes')->format('Y-m-d H:i:s.u');if($end!==null){$end=self::date($end,'ends_at');}if($end<=$start){throw new ValidationFailure('ends_at must be after starts_at','ends_at');}
        $ids=$d['contact_ids'];if($d['contact_id']&&!in_array($d['contact_id'],$ids,true)){array_unshift($ids,$d['contact_id']);}
        if($d['conversation_id']!==null){$conv=$this->db->one('conversations',array('id'=>$d['conversation_id']));if(!in_array($conv['contact_id'],$ids,true)){array_unshift($ids,$conv['contact_id']);}}
        elseif($ids&&$this->db->one('contacts',array('id'=>$ids[0]))){$conv=$this->db->one('conversations',array('contact_id'=>$ids[0],'channel'=>'sms'));if(!$conv){$conv=$this->records->create('conversations',array('contact_id'=>$ids[0]));}$d['conversation_id']=$conv['id'];}
        $d['ends_at']=$end;$d['tags_json']=$d['tags']?json_encode(self::cleanTags($d['tags']),JSON_THROW_ON_ERROR):null;$d['reminder_minutes_json']=null;$d['created_by']=$user['username'];foreach(array('contact_ids','contact_id','duration_minutes','tags','reminder_minutes') as $key){unset($d[$key]);}
        foreach($d as $key=>&$v){if(is_string($v)&&!in_array($key,array('starts_at','ends_at','created_by'),true)){$v=Compat::strip($v);if($v===''){$v=null;}}}unset($v);
        $r=$this->records->create('meetings',$d);$primary=$this->sync($r,$ids);$this->change($r,array('contact_id'=>$primary));$out=$this->read($r['id']);$out['invite']=array('sent'=>0,'skipped'=>0);return $out;
    }
    public function update($id,$body){
        $old=$this->meeting($id);$d=self::input($body,true);$this->noDelivery($d);$this->references($d);$patch=$d;foreach(array('duration_minutes','contact_ids','tags','reminder_minutes','ends_at') as $key){unset($patch[$key]);}
        foreach($patch as $key=>&$v){if(is_string($v)&&!in_array($key,array('starts_at','ends_at'),true)){$v=Compat::strip($v);if($v===''){$v=null;}}}unset($v);
