        $patch['starts_at']=$start;if(isset($d['starts_at'])){$patch['reminders_sent_json']=null;$patch['invite_sent']=0;}
        foreach(array('tags'=>'tags_json','reminder_minutes'=>'reminder_minutes_json') as $key=>$column){if(array_key_exists($key,$d)){$v=$key==='tags'?self::cleanTags($d[$key]):self::cleanMinutes($d[$key]);$patch[$column]=$v?json_encode($v,JSON_THROW_ON_ERROR):null;}}
