    public function setStatus($id,$status,$notes=null){if(!in_array($status,self::STATUSES,true)){throw new ValidationFailure('Unsupported status','status');}$r=$this->meeting($id);$p=array('status'=>$status);if($notes!==null){self::input((object)array('outcome_notes'=>$notes),true);$text=Compat::strip($notes);$p['outcome_notes']=$text===''?null:$text;}$this->change($r,$p,true);if($status==='completed'&&$r['contact_id']){$c=$this->db->one('contacts',array('id'=>$r['contact_id']));if($c&&in_array($c['lead_status'],array('new','contacted','replied','meeting'),true)&&$c['lead_status']!=='contacted'){if($this->db->update('contacts',array('lead_status'=>'contacted','updated_at'=>$this->records->now()),array('id'=>$c['id'],'lead_status'=>$c['lead_status']))!==1){throw new AuthFailure(409,'Contact changed. Retry.');}}}return $this->read($id);}
    public function delete($id){$old=$this->meeting($id);$this->db->delete('meeting_attendees',array('meeting_id'=>$id));if($this->db->delete('meetings',$old)!==1){throw new AuthFailure(409,'Meeting changed. Reload and retry.');}}
    public function listing(array $q=array()){
        $page=isset($q['page'])?DataRoutes::integer($q['page'],'page',1,1000000):1;$per=isset($q['per_page'])?DataRoutes::integer($q['per_page'],'per_page',1,500):100;$where=array('1=1');$args=array();
        foreach(array('date_from','date_to') as $key){$range=DataRoutes::text($q,$key,null,null,100);if($range!==null&&$range!==''){try{$date=self::date(Compat::strip($range),$key);$where[]=$key==='date_from'?'m.ends_at >= %s':'m.starts_at <= %s';$args[]=$date;}catch(ValidationFailure $e){/* Source ignores malformed optional ranges. */}}}
        if(isset($q['upcoming_only'])&&DataRoutes::boolean($q['upcoming_only'],'upcoming_only')){$where[]="m.starts_at >= %s AND m.status IN ('scheduled','confirmed')";$args[]=$this->records->now();}
        foreach(array('contact_id','conversation_id') as $key){if(isset($q[$key])){$id=DataRoutes::integer($q[$key],$key);if($id){$where[]=$key==='contact_id'?'(m.contact_id=%d OR EXISTS (SELECT 1 FROM '.$this->table('meeting_attendees').' a WHERE a.meeting_id=m.id AND a.contact_id=%d))':'m.conversation_id=%d';$args[]=$id;if($key==='contact_id'){$args[]=$id;}}}}
        foreach(array('status','event_type') as $key){$v=DataRoutes::text($q,$key);if($v!==null&&$v!==''&&$v!=='all'){$where[]='m.'.$key.'=%s';$args[]=$v;}}
        foreach(array('tag','search') as $key){$v=DataRoutes::text($q,$key,null,null,1000);if($v!==null&&$v!==''){$where[]=$key==='tag'?"LOWER(m.tags_json) LIKE LOWER(%s)":"(LOWER(m.title) LIKE LOWER(%s) OR LOWER(m.description) LIKE LOWER(%s) OR LOWER(m.location) LIKE LOWER(%s))";$term=$key==='tag'?'%"'.$v.'"%':'%'.$v.'%';$args[]=$term;if($key==='search'){$args[]=$term;$args[]=$term;}}}
        $from=' FROM '.$this->table('meetings').' m WHERE '.implode(' AND ',$where);$total=(int)$this->db->rows('SELECT COUNT(*) AS n'.$from,$args)[0]['n'];$rows=$this->db->rows('SELECT m.*'.$from.' ORDER BY m.starts_at ASC,m.id ASC LIMIT %d OFFSET %d',array_merge($args,array($per,($page-1)*$per)));$bytes=0;return array('total'=>$total,'items'=>array_map(function($r)use(&$bytes){return $this->out($this->db->decode('meetings',$r),$bytes);},$rows));
    }
    public function tags(){ $counts=array();$last=0;do{$rows=$this->db->rows('SELECT id,tags_json FROM '.$this->table('meetings').' WHERE id>%d ORDER BY id LIMIT 50',array($last));foreach($rows as $r){$last=(int)$r['id'];foreach(self::listJson($r['tags_json']) as $v){$name=Compat::strip(Attachments::truth($v)?Attachments::pythonText($v):'');if($name!==''){$counts[$name]=($counts[$name]??0)+1;}}}if(count($counts)>10000){throw new AuthFailure(413,'Too many calendar tags.');}}while(count($rows)===50);$names=array_keys($counts);usort($names,function($a,$b)use($counts){return $counts[$b]<=>$counts[$a]?:strcmp(Compat::lower((string)$a),Compat::lower((string)$b));});return array('items'=>array_map(function($name)use($counts){return array('name'=>(string)$name,'count'=>$counts[$name]);},$names));}
    public static function placeholders(array $r){$d=(new \DateTimeImmutable($r['starts_at'],new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('UTC'));return array('meeting_title'=>$r['title']??'','meeting_date'=>$d->format('D, d M Y'),'meeting_time'=>$d->format('g:i A'),'meeting_datetime'=>str_replace(' 0',' ',$d->format('D, d M Y').' at '.$d->format('h:i A')),'meeting_location'=>$r['location']?'at '.$r['location'].'.':'','meeting_link'=>$r['meeting_link']??'');}
    public function preview($id,array $q){$r=$this->meeting($id);$kind=DataRoutes::text($q,'kind','invite');if(!in_array($kind,array('invite','reminder'),true)){throw new ValidationFailure('kind must be invite or reminder','kind');}$template=isset($q['template_id'])?DataRoutes::integer($q['template_id'],'template_id'):$r[$kind.'_template_id'];$body=DataRoutes::text($q,'body',$r[$kind.'_body'],null,100000);if($body===null||Compat::strip($body)===''){$t=$template?$this->db->one('templates',array('id'=>$template,'is_active'=>1)):null;$body=$t?$t['body']:($kind==='invite'?self::INVITE:self::REMINDER);}$cid=isset($q['contact_id'])?DataRoutes::integer($q['contact_id'],'contact_id'):$r['contact_id'];$c=$cid?$this->db->one('contacts',array('id'=>$cid)):null;$values=self::placeholders($r);$values['meeting_when']='soon';list($a,$f)=(new Variables($this->db))->maps();$text=Templating::render($body,$c,$a,$f,'drop',array(),$values);list($chars,$segments)=Templating::segments($text);return array('kind'=>$kind,'body'=>$text,'char_count'=>$chars,'segment_count'=>$segments);}
    private static function body($request){if(strlen($request->get_body())>2097152){throw new AuthFailure(413,'Calendar request is too large.');}return DataRoutes::body($request);}
    public static function handle($request,array $context,array $user,&$status){$path=trim(substr($request->get_route(),strlen('/sender-suite/v1/')),'/');$method=$request->get_method();$s=new self($context['db']);$q=$request->get_query_params();
        if($path==='calendar'){if($method==='GET'){return $s->listing($q);}if($method==='POST'){$out=$s->create(self::body($request),$user);$status=201;return $out;}}
        if($method==='GET'){if($path==='calendar/tags'||$path==='calendar/tags/all'){return $s->tags();}if($path==='calendar/upcoming'){$per=isset($q['limit'])?DataRoutes::integer($q['limit'],'limit',1,50):5;return $s->listing(array('per_page'=>$per,'upcoming_only'=>true,'contact_id'=>$q['contact_id']??null));}if($path==='calendar/day'){$raw=DataRoutes::text($q,'date');if($raw===null||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',Compat::strip($raw))){throw new ValidationFailure('date must be YYYY-MM-DD','date');}$day=self::date(Compat::strip($raw),'date');$end=(new \DateTimeImmutable($day,new \DateTimeZone('UTC')))->modify('+1 day')->format('Y-m-d H:i:s.u');$out=$s->listing(array('date_from'=>$day,'date_to'=>substr($end,0,10).'T00:00:00Z','per_page'=>200));return array('date'=>Compat::strip($raw),'count'=>$out['total'],'items'=>$out['items']);}}
